package in.safeway.app;
import javax.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="safety_notifications") public class SafetyNotification{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;@ManyToOne(optional=false)@JoinColumn(name="recipient_id")public User recipient;@ManyToOne @JoinColumn(name="actor_id")public User actor;public String type;@Column(length=1000)public String message;public LocalDateTime createdAt;public boolean readFlag;public SafetyNotification(){}public SafetyNotification(User r,User a,String t,String m){recipient=r;actor=a;type=t;message=m;createdAt=LocalDateTime.now();readFlag=false;}}